69         // Frame hierarchy for rigid body and skeletal animation
70         struct ModelBone
71         {
72             ModelBone() noexcept :
73                 parentIndex(c_Invalid),
74                 childIndex(c_Invalid),
75                 siblingIndex(c_Invalid)
76             {
77             }
78 
79             ModelBone(uint32_t parent, uint32_t child, uint32_t sibling) noexcept :
80                 parentIndex(parent),
81                 childIndex(child),
82                 siblingIndex(sibling)
83             {
84             }
85 
86             uint32_t            parentIndex;
87             uint32_t            childIndex;
88             uint32_t            siblingIndex;
89             std::wstring        name;
90 
91             using Collection = std::vector<ModelBone>;
92 
93             static constexpr uint32_t c_Invalid = uint32_t(-1);
94 
95             struct aligned_deleter { void operator()(void* p) noexcept { _aligned_free(p); } };
96 
97             using TransformArray = std::unique_ptr<XMMATRIX[], aligned_deleter>;
98 
99             static TransformArray MakeArray(size_t count)
100             {
101                 void* temp = _aligned_malloc(sizeof(XMMATRIX) * count, 16);
102                 if (!temp)
103                     throw std::bad_alloc();
104                 return TransformArray(static_cast<XMMATRIX*>(temp));
105             }
106         };
