108         //------------------------------------------------------------------------------
109         // Each mesh part is a submesh with a single effect
110         class ModelMeshPart
111         {
112         public:
113             ModelMeshPart(uint32_t partIndex) noexcept;
114 
115             ModelMeshPart(ModelMeshPart&&) = default;
116             ModelMeshPart& operator= (ModelMeshPart&&) = default;
117 
