120 
121             virtual ~ModelMeshPart();
122 
123             using Collection = std::vector<std::unique_ptr<ModelMeshPart>>;
124             using DrawCallback = std::function<void(_In_ ID3D12GraphicsCommandList* commandList, const ModelMeshPart& part)>;
125             using InputLayoutCollection = std::vector<D3D12_INPUT_ELEMENT_DESC>;
126 
127             uint32_t                                                partIndex;      // Unique index assigned per-part in a model.
128             uint32_t                                                materialIndex;  // Index of the material spec to use
129             uint32_t                                                indexCount;
130             uint32_t                                                startIndex;
131             int32_t                                                 vertexOffset;
132             uint32_t                                                vertexStride;
133             uint32_t                                                vertexCount;
134             uint32_t                                                indexBufferSize;
135             uint32_t                                                vertexBufferSize;
136             D3D_PRIMITIVE_TOPOLOGY                                  primitiveType;
137             DXGI_FORMAT                                             indexFormat;
138             SharedGraphicsResource                                  indexBuffer;
139             SharedGraphicsResource                                  vertexBuffer;
140             Microsoft::WRL::ComPtr<ID3D12Resource>                  staticIndexBuffer;
141             Microsoft::WRL::ComPtr<ID3D12Resource>                  staticVertexBuffer;
142             std::shared_ptr<InputLayoutCollection>                  vbDecl;
143 
144             // Draw mesh part
145             void __cdecl Draw(_In_ ID3D12GraphicsCommandList* commandList) const;
146 
147             void __cdecl DrawInstanced(_In_ ID3D12GraphicsCommandList* commandList, uint32_t instanceCount, uint32_t startInstance = 0) const;
148 
149             //
150             // Utilities for drawing multiple mesh parts
151             //
152 
153             // Draw the mesh
154             static void __cdecl DrawMeshParts(_In_ ID3D12GraphicsCommandList* commandList, const Collection& meshParts);
155 
156             // Draw the mesh with an effect
157             static void __cdecl DrawMeshParts(_In_ ID3D12GraphicsCommandList* commandList, const Collection& meshParts, _In_ IEffect* effect);
158 
159             // Draw the mesh with a callback for each mesh part
160             static void __cdecl DrawMeshParts(_In_ ID3D12GraphicsCommandList* commandList, const Collection& meshParts, DrawCallback callback);
161 
162             // Draw the mesh with a range of effects that mesh parts will index into.
163             // Effects can be any IEffect pointer type (including smart pointer). Value or reference types will not compile.
164             // The iterator passed to this method should have random access capabilities for best performance.
165             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
166             static void DrawMeshParts(
167                 _In_ ID3D12GraphicsCommandList* commandList,
168                 const Collection& meshParts,
169                 TEffectIterator partEffects)
170             {
171                 // This assert is here to prevent accidental use of containers that would cause undesirable performance penalties.
172                 static_assert(
173                     std::is_base_of<std::random_access_iterator_tag, TEffectIteratorCategory>::value,
174                     "Providing an iterator without random access capabilities -- such as from std::list -- is not supported.");
175 
176                 for (const auto& it : meshParts)
177                 {
178                     auto part = it.get();
179                     assert(part != nullptr);
180 
181                     // Get the effect at the location specified by the part's material
182                     TEffectIterator effect_iterator = partEffects;
183                     std::advance(effect_iterator, part->partIndex);
184 
185                     // Apply the effect and draw
186                     (*effect_iterator)->Apply(commandList);
187                     part->Draw(commandList);
188                 }
189             }
190 
191             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
192             static void XM_CALLCONV DrawMeshParts(
193                 _In_ ID3D12GraphicsCommandList* commandList,
194                 const Collection& meshParts,
195                 FXMMATRIX world,
196                 TEffectIterator partEffects)
197             {
198                 // This assert is here to prevent accidental use of containers that would cause undesirable performance penalties.
199                 static_assert(
200                     std::is_base_of<std::random_access_iterator_tag, TEffectIteratorCategory>::value,
201                     "Providing an iterator without random access capabilities -- such as from std::list -- is not supported.");
202 
203                 for (const auto& it : meshParts)
204                 {
205                     auto part = it.get();
206                     assert(part != nullptr);
207 
208                     // Get the effect at the location specified by the part's material
209                     TEffectIterator effect_iterator = partEffects;
210                     std::advance(effect_iterator, part->partIndex);
211 
212                     auto imatrices = dynamic_cast<IEffectMatrices*>((*effect_iterator).get());
213                     if (imatrices)
214                     {
215                         imatrices->SetWorld(world);
216                     }
217 
218                     // Apply the effect and draw
219                     (*effect_iterator)->Apply(commandList);
220                     part->Draw(commandList);
221                 }
222             }
223 
224             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
225             static void XM_CALLCONV DrawSkinnedMeshParts(
226                 _In_ ID3D12GraphicsCommandList* commandList,
227                 const ModelMesh& mesh,
228                 const Collection& meshParts,
229                 size_t nbones,
230                 _In_reads_(nbones) const XMMATRIX* boneTransforms,
231                 FXMMATRIX world,
232                 TEffectIterator partEffects);
233         };
