270             void __cdecl DrawOpaque(_In_ ID3D12GraphicsCommandList* commandList, ModelMeshPart::DrawCallback callback) const;
271             void __cdecl DrawAlpha(_In_ ID3D12GraphicsCommandList* commandList, ModelMeshPart::DrawCallback callback) const;
272 
273             // Draw the mesh with a range of effects that mesh parts will index into.
274             // TEffectPtr can be any IEffect pointer type (including smart pointer). Value or reference types will not compile.
275             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
276             void DrawOpaque(_In_ ID3D12GraphicsCommandList* commandList, TEffectIterator effects) const
277             {
278                 ModelMeshPart::DrawMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, opaqueMeshParts, effects);
279             }
280             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
281             void DrawAlpha(_In_ ID3D12GraphicsCommandList* commandList, TEffectIterator effects) const
282             {
283                 ModelMeshPart::DrawMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, alphaMeshParts, effects);
284             }
285 
286             // Draw rigid-body with bones.
287             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
288             void XM_CALLCONV DrawOpaque(
289                 _In_ ID3D12GraphicsCommandList* commandList,
290                 size_t nbones,
291                 _In_reads_(nbones) const XMMATRIX* boneTransforms,
292                 FXMMATRIX world,
293                 TEffectIterator effects) const
294             {
295                 assert(nbones > 0 && boneTransforms != nullptr);
296                 XMMATRIX local;
297                 if (boneIndex != ModelBone::c_Invalid && boneIndex < nbones)
298                 {
299                     local = XMMatrixMultiply(boneTransforms[boneIndex], world);
300                 }
301                 else
302                 {
303                     local = world;
304                 }
305 
306                 ModelMeshPart::DrawMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, opaqueMeshParts, local, effects);
307             }
308 
309             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
310             void XM_CALLCONV DrawAlpha(
311                 _In_ ID3D12GraphicsCommandList* commandList,
312                 size_t nbones,
313                 _In_reads_(nbones) const XMMATRIX* boneTransforms,
314                 FXMMATRIX world,
315                 TEffectIterator effects) const
316             {
317                 assert(nbones > 0 && boneTransforms != nullptr);
318                 XMMATRIX local;
319                 if (boneIndex != ModelBone::c_Invalid && boneIndex < nbones)
320                 {
321                     local = XMMatrixMultiply(boneTransforms[boneIndex], world);
322                 }
323                 else
324                 {
325                     local = world;
326                 }
327 
328                 ModelMeshPart::DrawMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, alphaMeshParts, local, effects);
329             }
330 
331             // Draw using skinning given bone transform array.
332             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
333             void XM_CALLCONV DrawSkinnedOpaque(
334                 _In_ ID3D12GraphicsCommandList* commandList,
335                 size_t nbones,
336                 _In_reads_(nbones) const XMMATRIX* boneTransforms,
337                 FXMMATRIX world,
338                 TEffectIterator effects) const
339             {
340                 ModelMeshPart::DrawSkinnedMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, *this, opaqueMeshParts,
341                     nbones, boneTransforms, world, effects);
342             }
343 
344             template<typename TEffectIterator, typename TEffectIteratorCategory = typename TEffectIterator::iterator_category>
345             void XM_CALLCONV DrawSkinnedAlpha(
346                 _In_ ID3D12GraphicsCommandList* commandList,
347                 size_t nbones,
348                 _In_reads_(nbones) const XMMATRIX* boneTransforms,
349                 FXMMATRIX world,
350                 TEffectIterator effects) const
351             {
352                 ModelMeshPart::DrawSkinnedMeshParts<TEffectIterator, TEffectIteratorCategory>(commandList, *this, alphaMeshParts,
353                     nbones, boneTransforms, world, effects);
354             }
