359         // A model consists of one or more meshes
360         class Model
361         {
362         public:
363             Model() noexcept;
364 
365             Model(Model&&) = default;
366             Model& operator= (Model&&) = default;
367 
368             Model(Model const& other);
369             Model& operator= (Model const& rhs);
