373             using EffectCollection = std::vector<std::shared_ptr<IEffect>>;
374             using ModelMaterialInfo = IEffectFactory::EffectInfo;
375             using ModelMaterialInfoCollection = std::vector<ModelMaterialInfo>;
376             using TextureCollection = std::vector<std::wstring>;
377 
378             // The Model::Draw* functions use variadic templates and perfect-forwarding in order to support future
379             // overloads to the ModelMesh::Draw* family of functions. This means that a new ModelMesh overload can be
380             // added, removed or altered, but the Model routines will still remain compatible. The correct ModelMesh
381             // overload will be selected by the compiler depending on the arguments you provide to the Model method.
382 
383             // Draw all the meshes in the model.
384             template<typename... TForwardArgs> void DrawOpaque(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
385             {
386                 // Draw opaque parts
387                 for (const auto& it : meshes)
388                 {
389                     auto mesh = it.get();
390                     assert(mesh != nullptr);
391 
392                     mesh->DrawOpaque(commandList, std::forward<TForwardArgs>(args)...);
393                 }
394             }
395 
396             template<typename... TForwardArgs> void DrawAlpha(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
397             {
398                 // Draw alpha parts
399                 for (const auto& it : meshes)
400                 {
401                     auto mesh = it.get();
402                     assert(mesh != nullptr);
403 
404                     mesh->DrawAlpha(commandList, std::forward<TForwardArgs>(args)...);
405                 }
406             }
407 
408             template<typename... TForwardArgs> void Draw(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
409             {
410                 DrawOpaque(commandList, args...);
411                 DrawAlpha(commandList, std::forward<TForwardArgs>(args)...);
412             }
413 
414             // Draw mesh using skinning given bone transform array.
415             template<typename... TForwardArgs> void DrawSkinnedOpaque(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
416             {
417                 // Draw opaque parts
418                 for (const auto& it : meshes)
419                 {
420                     auto mesh = it.get();
421                     assert(mesh != nullptr);
422 
423                     mesh->DrawSkinnedOpaque(commandList, std::forward<TForwardArgs>(args)...);
424                 }
425             }
426 
427             template<typename... TForwardArgs> void DrawSkinnedAlpha(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
428             {
429                 // Draw alpha parts
430                 for (const auto& it : meshes)
431                 {
432                     auto mesh = it.get();
433                     assert(mesh != nullptr);
434 
435                     mesh->DrawSkinnedAlpha(commandList, std::forward<TForwardArgs>(args)...);
436                 }
437             }
438 
439             template<typename... TForwardArgs> void DrawSkinned(_In_ ID3D12GraphicsCommandList* commandList, TForwardArgs&&... args) const
440             {
441                 DrawSkinnedOpaque(commandList, args...);
442                 DrawSkinnedAlpha(commandList, std::forward<TForwardArgs>(args)...);
443             }
