530             // Utility function for getting a GPU descriptor for a mesh part/material index. If there is no texture the
531             // descriptor will be zero.
532             D3D12_GPU_DESCRIPTOR_HANDLE __cdecl GetGpuTextureHandleForMaterialIndex(uint32_t materialIndex, _In_ ID3D12DescriptorHeap* heap, _In_ size_t descriptorSize, _In_ size_t descriptorOffset) const
533             {
534                 D3D12_GPU_DESCRIPTOR_HANDLE handle = {};
535 
536                 if (materialIndex >= materials.size())
537                     return handle;
538 
539                 const int textureIndex = materials[materialIndex].diffuseTextureIndex;
540                 if (textureIndex == -1)
541                     return handle;
542 
543             #if defined(_MSC_VER) || !defined(_WIN32)
544                 handle = heap->GetGPUDescriptorHandleForHeapStart();
545             #else
546                 std::ignore = heap->GetGPUDescriptorHandleForHeapStart(&handle);
547             #endif
548                 handle.ptr += static_cast<UINT64>(descriptorSize * (UINT64(textureIndex) + UINT64(descriptorOffset)));
549 
550                 return handle;
551             }
552 
