620         template<typename TEffectIterator, typename TEffectIteratorCategory>
621         void XM_CALLCONV ModelMeshPart::DrawSkinnedMeshParts(
622             _In_ ID3D12GraphicsCommandList* commandList,
623             const ModelMesh& mesh,
624             const ModelMeshPart::Collection& meshParts,
625             size_t nbones,
626             _In_reads_(nbones) const XMMATRIX* boneTransforms,
627             FXMMATRIX world,
628             TEffectIterator partEffects)
629         {
630             // This assert is here to prevent accidental use of containers that would cause undesirable performance penalties.
631             static_assert(
632                 std::is_base_of<std::random_access_iterator_tag, TEffectIteratorCategory>::value,
633                 "Providing an iterator without random access capabilities -- such as from std::list -- is not supported.");
634 
635             assert(nbones > 0 && boneTransforms != nullptr);
636 
637             ModelBone::TransformArray temp;
638 
639             for (const auto& mit : meshParts)
640             {
641                 auto part = mit.get();
642                 assert(part != nullptr);
643 
644                 // Get the effect at the location specified by the part's material
645                 TEffectIterator effect_iterator = partEffects;
646                 std::advance(effect_iterator, part->partIndex);
647 
648                 auto imatrices = dynamic_cast<IEffectMatrices*>((*effect_iterator).get());
649                 if (imatrices)
650                 {
651                     imatrices->SetWorld(world);
652                 }
653 
654                 auto iskinning = dynamic_cast<IEffectSkinning*>((*effect_iterator).get());
655                 if (iskinning)
656                 {
657                     if (mesh.boneInfluences.empty())
658                     {
659                         // Direct-mapping of vertex bone indices to our master bone array
660                         iskinning->SetBoneTransforms(boneTransforms, nbones);
661                     }
662                     else
663                     {
664                         if (!temp)
665                         {
666                             // Create the influence mapped bones on-demand.
667                             temp = ModelBone::MakeArray(IEffectSkinning::MaxBones);
668 
669                             size_t count = 0;
670                             for (auto it : mesh.boneInfluences)
671                             {
672                                 ++count;
673                                 if (count > IEffectSkinning::MaxBones)
674                                 {
675                                     throw std::runtime_error("Too many bones for skinning");
676                                 }
677 
678                                 if (it >= nbones)
679                                 {
680                                     throw std::runtime_error("Invalid bone influence index");
681                                 }
682 
683                                 temp[count - 1] = boneTransforms[it];
684                             }
685 
686                             assert(count == mesh.boneInfluences.size());
687                         }
688 
689                         iskinning->SetBoneTransforms(temp.get(), mesh.boneInfluences.size());
690                     }
691                 }
692                 else if (imatrices)
693                 {
694                     // Fallback for if we encounter a non-skinning effect in the model
695                     XMMATRIX bm = (mesh.boneIndex != ModelBone::c_Invalid && mesh.boneIndex < nbones)
696                         ? boneTransforms[mesh.boneIndex] : XMMatrixIdentity();
697 
698                     imatrices->SetWorld(XMMatrixMultiply(bm, world));
699                 }
700 
701                 // Apply the effect and draw
702                 (*effect_iterator)->Apply(commandList);
703                 part->Draw(commandList);
704             }
705         }
706 
707     #ifdef __clang__
708     #pragma clang diagnostic push
709     #pragma clang diagnostic ignored "-Wdeprecated-dynamic-exception-spec"
710     #endif
711 
712         DEFINE_ENUM_FLAG_OPERATORS(ModelLoaderFlags);
713 
714     #ifdef __clang__
715     #pragma clang diagnostic pop
716     #endif
717     }
718 }
